// ---------- Identidade visual CCIB ----------
const NAVY = "#173A63";
const ORANGE = "#F07D28";
const BG = "#F5F6F8";
const LOGO_CCIB = "data:image/png;base64,";

const MOEDAS = [
  { valor: "BRL", label: "Real (R$)", simbolo: "R$" },
  { valor: "USD", label: "Dólar (US$)", simbolo: "US$" },
  { valor: "INR", label: "Rupia (₹)", simbolo: "₹" },
];

const fmtValor = (v, moeda) => {
  if (v === null || v === undefined || v === "") return "—";
  const m = moeda || "BRL";
  if (m === "USD") return "US$" + Number(v).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (m === "INR") return "₹" + Number(v).toLocaleString("en-IN");
  return Number(v).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
};

const fmtData = (d) => {
  if (!d) return "—";
  const [ano, mes, dia] = d.split("-");
  return `${dia}/${mes}/${ano}`;
};

const fmtDataHora = (iso) => {
  if (!iso) return "";
  const d = new Date(iso);
  return d.toLocaleDateString("pt-BR") + " às " + d.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
};

const hojeDia = 27; // dia do mês atual, para status de vencimento
const MES_ATUAL = "2026-07";

// Meses disponíveis no filtro: começa no início de 2026 e segue para frente
const NOMES_MES = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];
const gerarMeses = () => {
  const lista = [];
  let ano = 2026;
  let mes = 1; // janeiro
  for (let i = 0; i < 24; i++) {
    const mm = String(mes).padStart(2, "0");
    lista.push({ valor: `${ano}-${mm}`, label: NOMES_MES[mes - 1], ano });
    mes += 1;
    if (mes > 12) {
      mes = 1;
      ano += 1;
    }
  }
  return lista;
};
const MESES = gerarMeses();
const MESES_POR_ANO = MESES.reduce((acc, m) => {
  (acc[m.ano] = acc[m.ano] || []).push(m);
  return acc;
}, {});
const labelMes = (valor) => MESES.find((m) => m.valor === valor)?.label + "/" + valor.split("-")[0].slice(2);
const fimDoMes = (valor) => {
  const [ano, mes] = valor.split("-").map(Number);
  return new Date(ano, mes, 0, 23, 59, 59);
};

// Quando o usuário só marca "pago" sem escolher uma data específica, usamos hoje
// (se for o mês atual) ou o dia de vencimento do próprio mês como data de referência.
const dataParaMarcarPago = (mes, diaVencimento) => {
  const hoje = new Date();
  const mesDeHoje = `${hoje.getFullYear()}-${String(hoje.getMonth() + 1).padStart(2, "0")}`;
  if (mes === mesDeHoje) return hoje.toISOString().slice(0, 10);
  const dia = diaVencimento && diaVencimento !== "" ? String(diaVencimento).padStart(2, "0") : "01";
  return `${mes}-${dia}`;
};

const statusDe = (c, mes) => {
  if (!c.ativo) return { texto: "Desligado", cor: "#9AA3B2" };
  if (c.situacaoManual === "Em atraso") return { texto: "Atrasado", cor: "#C1453D" };
  const pago = c.pagamentos ? c.pagamentos[mes] : "";
  if (pago) return { texto: "Pago", cor: "#2F7A5C" };
  if (mes > MES_ATUAL) return { texto: "Mês futuro", cor: "#B7BEC9" };
  if (mes === MES_ATUAL) {
    if (c.diaVencimento && Number(c.diaVencimento) < hojeDia) return { texto: "Atrasado", cor: "#C1453D" };
    return { texto: "Em dia", cor: NAVY };
  }
  // mês já fechado no passado e sem pagamento registrado
  return { texto: "Não pago", cor: "#C1453D" };
};

// Calcula o comportamento histórico de pagamento do cliente: dia médio do mês em que
// costuma pagar, e a média de dias de atraso/antecedência em relação ao vencimento.
const perfilPagamento = (c) => {
  const pagamentos = c.pagamentos || {};
  const dias = Object.values(pagamentos)
    .filter((d) => d)
    .map((d) => Number(d.split("-")[2]));

  if (dias.length === 0) return { temDados: false };

  const diaMedio = dias.reduce((s, d) => s + d, 0) / dias.length;

  let atrasoMedio = null;
  if (c.diaVencimento) {
    const venc = Number(c.diaVencimento);
    const diffs = dias.map((d) => d - venc);
    atrasoMedio = diffs.reduce((s, d) => s + d, 0) / diffs.length;
  }

  return {
    temDados: true,
    diaMedio: Math.round(diaMedio),
    atrasoMedio: atrasoMedio === null ? null : Math.round(atrasoMedio * 10) / 10,
    qtdMeses: dias.length,
  };
};

