// Aplica um lote de atualizações (novos associados + patches) numa lista de clientes.
// Função pura — usada tanto para aplicar automaticamente ao abrir o painel quanto,
// se precisar, manualmente.
let contadorIdLote = 0;
const mesclarLote = (clientesAtual, lote) => {
  let lista = [...clientesAtual];
  lote.itens.forEach((item) => {
    const idUnico = () => `${Date.now()}-${contadorIdLote++}`;
    if (item.tipo === "novo") {
      const novoCliente = {
        ...clienteVazio(),
        ...item.cliente,
        id: idUnico(),
        historico: item.notaHistorico
          ? [{ id: idUnico(), texto: item.notaHistorico, data: new Date().toISOString() }]
          : [],
      };
      lista = [novoCliente, ...lista];
    } else {
      lista = lista.map((c) => {
        if (c.nome.trim().toLowerCase() !== item.nomeExistente.trim().toLowerCase()) return c;
        const contatoMesclado = item.contatoNovo
          ? Array.from(new Set(`${c.contato} ${item.contatoNovo}`.split(/[\s;]+/).filter(Boolean))).join(" ")
          : c.contato;
        const novoHistorico = item.notaHistorico
          ? [{ id: idUnico(), texto: item.notaHistorico, data: new Date().toISOString() }, ...c.historico]
          : c.historico;
        return { ...c, ...item.campos, contato: contatoMesclado, historico: novoHistorico };
      });
    }
  });
  return lista;
};

